// قبل از این آدرسِ کوتاه‌شده می‌نشیند: ۴ نویسه + … + ۴ نویسه.
export function shortAddr(a) {
  const s = typeof a === "string" ? a : "";
  return s.length > 9 ? s.slice(0, 4) + "…" + s.slice(-4) : s;
}

const MON = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export function shortDate(d) {
  return (+d.slice(8, 10)) + " " + MON[+d.slice(5, 7) - 1];
}
export function longDate(d) {
  return shortDate(d) + " " + d.slice(0, 4);
}
// تاریخِ UTC پس از n روز (n منفی هم می‌شود).
export function addDays(d, n) {
  return new Date(Date.parse(d + "T00:00:00Z") + n * 86400000).toISOString().slice(0, 10);
}
// آیا رشته یک روزِ واقعیِ تقویم است؟ (REPORT_DATE_RE فقط شکل را می‌سنجد: 2026-13-45 را هم می‌پذیرد.)
export function isRealDate(d) {
  return typeof d === "string" && /^\d{4}-\d{2}-\d{2}$/.test(d) &&
    !Number.isNaN(Date.parse(d + "T00:00:00Z")) && addDays(d, 0) === d;
}

function esc(s) {
  return String(s == null ? "" : s).replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

/* ---------------------------------------------------------------------
   plainWhy — واژه‌نامه‌ی بسته‌ی why → یک جمله‌ی کوتاه و بی‌اصطلاح.
   Base: دقیقاً اعضای VD_BASE_WHY (worker/verdict.js) + meta:<عدد>/cover:<عدد>.
   Solana: خانواده‌ها با پیشوند (VD_SOL_WHY در worker/verdict_sol.js).
   هر چیزِ ناشناخته → «The check did not finish.» — هرگز خودِ کد.
   جمله‌ها عمداً «:» ندارند تا یک کدِ خام در متن نشت نکند. */
const WHY_UNKNOWN = "The check did not finish.";
const WHY_BASE = {
  "meta:timeout": "The token details did not load in time.",
  "meta:shape": "The token details came back in a form we could not read.",
  "no-amount": "No usable $100 amount could be worked out for this token.",
  "deadline": "The check ran out of time.",
  "rpc-down": "The network nodes did not answer.",
  "canary-dead": "The check's own test call failed, so the answer was not trusted.",
  "no-quote": "No pool was found to ask for a sell quote.",
  "proof-rpc": "The network nodes did not answer when we looked for proof of an empty pool.",
  "proof-no-quote": "A sell quote could not be proven either way.",
  "usdc-rpc": "The network nodes did not answer a second round of quote requests.",
  "usdc-no-proof": "A second round of quotes could not prove a sell route either way.",
  "cover:false": "No pool for this token was found on an exchange we check.",
  "cover:timeout": "The pool lookup did not answer in time.",
  "cover:shape": "The pool lookup returned something we could not read.",
  "internal": "The check hit an unexpected problem.",
  "v4:unproven": "Only a Uniswap v4 pool was found, and its emptiness could not be proven.",
  "sells:recent": "Other wallets sold this token in the last hour, so a missing quote was not trusted.",
  "sells:elsewhere": "This token sold on another pool in the last day, so a missing quote was not trusted.",
  "cause:unproven": "No sell route was found, but the reason could not be proven.",
};
const WHY_SOL = {
  "unsupported": "This address is not a token we can check.",
  "payer-balance": "The balance of the test wallet could not be confirmed.",
  "payer-holds": "The test wallet already held this token, so the test proved nothing.",
  "no-route": "Jupiter found no route for this token.",
  "too-big": "The simulated trade was too large to fit in one transaction.",
  "deadline": "The check ran out of time.",
  "internal": "The check hit an unexpected problem.",
  "sells:recent": "Other wallets sold this token in the last hour, so a failed sell was not trusted.",
  "sells:recent24": "Other wallets sold this token in the last day, so a failed sell was not trusted.",
  "sol:unconfirmed": "The simulated sell failed, but that is not reported until it is confirmed.",
};
const HTTP_BUSY = (n) => n === 0 || n === 429 || (n >= 500 && n <= 599);

export function plainWhy(chain, why) {
  if (typeof why !== "string") return WHY_UNKNOWN;
  if (chain === "base") {
    if (Object.prototype.hasOwnProperty.call(WHY_BASE, why)) return WHY_BASE[why];
    let m = /^meta:(\d{1,3})$/.exec(why);
    if (m) return HTTP_BUSY(+m[1]) ? "The token data service was busy or did not answer." : "The token data service returned an error.";
    m = /^cover:(\d{1,3})$/.exec(why);
    if (m) return HTTP_BUSY(+m[1]) ? "The pool lookup service was busy or did not answer." : "The pool lookup service returned an error.";
    return WHY_UNKNOWN;
  }
  if (chain === "solana") {
    if (Object.prototype.hasOwnProperty.call(WHY_SOL, why)) return WHY_SOL[why];
    let m = /^jup:(quote|swap-instructions)(?::(\d{1,3}))?$/.exec(why);
    if (m) {
      const n = m[2] === undefined ? -1 : +m[2];
      if (n === 0) return "The quote service did not answer in time; it will be tried again.";
      if (HTTP_BUSY(n)) return "The quote service was busy; it will be tried again.";
      return m[1] === "quote"
        ? "Jupiter would not quote a trade for this token."
        : "Jupiter would not build a trade for this token.";
    }
    m = /^rpc:(getBalance|getMultipleAccounts|simulateTransaction)(?::(-?\d{1,6}))?$/.exec(why);
    if (m) return "A Solana network node was busy or did not answer.";
    return WHY_UNKNOWN;
  }
  return WHY_UNKNOWN;
}

/* ---------------------------------------------------------------------
   شمارش — فقط از ردیف‌های گاردشده. */
const hasFollow = (r) => typeof r.follow === "string" && r.follow.length > 0;

export function dayCounts(date, rows) {
  const base = (Array.isArray(rows) ? rows : []).filter((r) => r && r.chain === "base");
  const sell = base.filter((r) => r.v === "sell");
  return {
    date,
    b: base.length,
    bSell: sell.length,
    bNo: base.filter((r) => r.v === "nosell").length,
    bNa: base.filter((r) => r.v !== "sell" && r.v !== "nosell").length,
    bEmpty: sell.filter((r) => r.follow === "pool-empty").length,
    bFollowed: sell.filter(hasFollow).length,
  };
}

function statsOf(rows) {
  const base = rows.filter((r) => r.chain === "base");
  const sol = rows.filter((r) => r.chain === "solana");
  const bs = base.filter((r) => r.v === "sell");
  // 🔴 فقط 0 < ret ≤ 100: بالاتر از ۱۰۰٪ یعنی قیمتِ فید و استخر هم‌نظر نبوده‌اند، نه سود.
  const rets = bs.map((r) => r.ret).filter((x) => typeof x === "number" && Number.isFinite(x) && x > 0 && x <= 100).sort((a, b) => a - b);
  const med = rets.length
    ? (rets.length % 2 ? rets[(rets.length - 1) / 2] : (rets[rets.length / 2 - 1] + rets[rets.length / 2]) / 2)
    : null;
  const nos = base.filter((r) => r.v === "nosell");
  return {
    b: base.length, bSell: bs.length, bNo: nos.length,
    bNa: base.filter((r) => r.v !== "sell" && r.v !== "nosell").length,
    bEmpty: bs.filter((r) => r.follow === "pool-empty").length,
    bFollowed: bs.filter(hasFollow).length,
    med,
    causeEmpty: nos.filter((r) => r.cause === "empty-pool").length,
    causeRevert: nos.filter((r) => r.cause === "sell-reverts").length,
    s: sol.length,
    sSell: sol.filter((r) => r.v === "sell").length,
    sNa: sol.filter((r) => r.v !== "sell" && r.v !== "nosell").length,
    sNo: sol.filter((r) => r.v === "nosell").length,
  };
}

const plural = (n, one, many) => n + " " + (n === 1 ? one : many);

export function reportLede(st, solana = true) {
  let t = solana
    ? plural(st.b, "new Base token", "new Base tokens") + " and " +
      plural(st.s, "new Solana token", "new Solana tokens") +
      (st.b + st.s === 1 ? " was checked." : " were checked.")
    : plural(st.b, "new Base token", "new Base tokens") + (st.b === 1 ? " was checked." : " were checked.");
  if (st.bFollowed > 0) {
    t += " " + st.bFollowed + " of the quoted tokens were re-checked 1–3 hours later. " +
      st.bEmpty + " had an empty pool.";
  }
  return t;
}

export function reportMetaDescription(date, st, solana = true) {
  if (!solana)
    return "On " + longDate(date) + " Zaexa checked " + plural(st.b, "new Base token", "new Base tokens") +
      ". Base: " + st.bSell + " had a sell route, " + st.bNo + " had none, " + st.bNa + " could not be checked.";
  return "On " + longDate(date) + " Zaexa checked " + plural(st.b, "new Base token", "new Base tokens") +
    " and " + plural(st.s, "Solana token", "Solana tokens") + ". Base: " + st.bSell + " had a sell route, " +
    st.bNo + " had none, " + st.bNa + " could not be checked. Solana: " + st.sSell +
    " passed the buy and sell test, " + st.sNa + " could not be checked.";
}

/* ---------------------------------------------------------------------
   جزیره‌ی JSON — « < > & » و جداکننده‌های خط به \uXXXX تا یک نامِ توکن هرگز
   نتواند تگ را ببندد. */
export function jsonForScript(obj) {
  return JSON.stringify(obj)
    .replace(/</g, "\\u003c").replace(/>/g, "\\u003e").replace(/&/g, "\\u0026")
    .replace(/\u2028/g, "\\u2028").replace(/\u2029/g, "\\u2029");
}

function islandRow(r) {
  const o = {
    chain: r.chain,
    address: typeof r.address === "string" ? r.address : "",
    // نمادِ خالی/«?» هرگز «$?» نمی‌شود: null می‌رود و کلاینت آدرسِ کوتاه نشان می‌دهد.
    symbol: typeof r.symbol === "string" && r.symbol.trim() !== "" && r.symbol.trim() !== "?" ? r.symbol : null,
    name: typeof r.name === "string" ? r.name : null,
    v: r.v === "sell" || r.v === "nosell" ? r.v : null,
    reserveUsd: typeof r.reserveUsd === "number" && Number.isFinite(r.reserveUsd) ? r.reserveUsd : null,
    checkedAt: typeof r.checkedAt === "string" ? r.checkedAt : null,
  };
  if (typeof r.cause === "string") o.cause = r.cause;
  if (typeof r.ret === "number" && Number.isFinite(r.ret)) o.ret = r.ret;
  if (hasFollow(r)) { o.follow = r.follow; if (typeof r.followAt === "string") o.followAt = r.followAt; }
  // why همیشه جمله است، نه کد.
  if (o.v === null) o.why = plainWhy(r.chain, r.why);
  return o;
}

/* ---------------------------------------------------------------------
   نمودار — SVGِ سمتِ سرور؛ هر ستون یک <a> است به /report/<روز>. */
function chartSvg(days, cur, firstDate) {
  // 🔴 ستونِ پیش از اولین گزارش هرگز کشیده نمی‌شود (دفاعِ دوم؛ مسیر هم همین را فیلتر می‌کند).
  days = days.filter((d) => !firstDate || d.date >= firstDate);
  const W = 1040, H = 250, L = 34, R = 8, T = 14, B = 30, pw = W - L - R, ph = H - T - B;
  const maxB = Math.max(0, ...days.map((d) => d.bSell + d.bNo + d.bNa));
  const step = maxB <= 100 ? 25 : maxB <= 300 ? 50 : maxB <= 600 ? 100 : 200;
  const max = Math.max(step, Math.ceil(maxB / step) * step);
  const y = (v) => T + ph - (v / max) * ph;
  const f = (n) => (Math.round(n * 10) / 10).toString();
  // پهنای هر ستون سقف دارد (۷۲) و گروه وسطِ نمودار می‌نشیند — با چند ستونِ کم میله‌ی غول‌پیکر نمی‌شود.
  const band = Math.min(pw / Math.max(days.length, 1), 72), bw = Math.min(24, band * 0.5);
  const x0 = L + (pw - band * days.length) / 2;
  let g = "";
  for (let v = 0; v <= max; v += step)
    g += '<line x1="' + L + '" x2="' + (W - R) + '" y1="' + f(y(v)) + '" y2="' + f(y(v)) +
      '" stroke="var(--line)" stroke-width="1"/><text x="' + (L - 8) + '" y="' + f(y(v) + 4) + '" text-anchor="end">' + v + "</text>";
  days.forEach((s, i) => {
    const x = x0 + band * i + band / 2 - bw / 2;
    let acc = 0, segs = "";
    const parts = [[s.bSell, "--s-sell"], [s.bNo, "--s-nosell"], [s.bNa, "--s-none"]];
    parts.forEach(([v, c], k, arr) => {
      if (!v) return;
      const y1 = y(acc + v), h = y(acc) - y1 - 2;
      acc += v;
      const last = arr.slice(k + 1).every((a) => !a[0]);
      segs += '<rect x="' + f(x) + '" y="' + f(y1 + (last ? 0 : 2)) + '" width="' + f(bw) + '" height="' +
        f(Math.max(h + (last ? 2 : 0), 1.5)) + '" rx="' + (last ? 4 : 0) + '" fill="var(' + c + ')"/>';
      if (last) segs += '<rect x="' + f(x) + '" y="' + f(y1 + 4) + '" width="' + f(bw) + '" height="' +
        f(Math.max(h - 2, 0)) + '" fill="var(' + c + ')"/>';
    });
    const label = shortDate(s.date) + ": " + s.bSell + " sell route, " + s.bNo + " no sell route, " + s.bNa + " not checked";
    g += '<a class="col' + (s.date === cur ? " sel" : "") + '" data-d="' + s.date + '" href="/report/' + s.date +
      '" aria-label="' + esc(label) + '"' + (s.date === cur ? ' aria-current="page"' : "") +
      '><rect class="hit" x="' + f(x0 + band * i + 2) + '" y="' + (T - 6) + '" width="' + f(band - 4) + '" height="' +
      (ph + B + 2) + '" rx="8" fill="transparent"/>' + segs + '<text x="' + f(x0 + band * i + band / 2) + '" y="' +
      (H - 9) + '" text-anchor="middle">' + esc(shortDate(s.date)) + "</text></a>";
  });
  return '<svg class="chart" id="chart" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="Stacked bars of Base check results per day">' + g + "</svg>";
}

